SELECT COALESCE(
  jsonb_agg(
    jsonb_build_object(
      'table_id', table_id,
      'label',    table_label,
      'seats',    table_seats,
      'zone',     table_zone
    ) ORDER BY table_seats, table_label
  ),
  '[]'::jsonb
) AS tables
FROM find_available_tables($1::uuid, $2::date, $3::time, $4::int);

