// Пустой tables — это не ошибка, а «на это время свободных столиков нет»: так же
// функция отвечает на закрытый день, прошедшее время и слишком большую компанию.
const CAST_ERRORS = ['22007', '22008', '22P02', '23514', 'invalid input syntax'];
const DOMAIN = [
  ['45000', 'restaurant_not_found'],
  ['45004', 'closed_at_requested_time'],
  ['45005', 'party_too_large'],
  ['45006', 'slot_in_past'],
  ['45015', 'table_not_available'],
  ['45016', 'table_already_booked'],
];

function toError(result) {
  const serialized = JSON.stringify(result);
  for (const [state, code] of DOMAIN) {
    if (serialized.includes(state) || serialized.includes(code)) {
      return { ok: false, error: code };
    }
  }
  for (const marker of CAST_ERRORS) {
    if (serialized.includes(marker)) return { ok: false, error: 'invalid_request' };
  }
  return { ok: false, error: 'unreachable' };
}

const result = $input.first().json;

if (Array.isArray(result.tables)) {
  return [{ json: { ok: true, tables: result.tables } }];
}

return [{ json: toError(result) }];
